// Solo dejamos pasar los adjuntos PDF (el resto se ignora)
const salida = [];
for (const item of $input.all()) {
  const binarios = item.binary || {};
  for (const [clave, archivo] of Object.entries(binarios)) {
    if (archivo.mimeType === 'application/pdf' || (archivo.fileName || '').toLowerCase().endsWith('.pdf')) {
      salida.push({ json: { remitente: item.json.from, archivo: archivo.fileName }, binary: { data: archivo } });
    }
  }
}
return salida;

// Interpreta el texto de la factura con expresiones regulares (misma idea que src/parser.ts)
const num = (t) => { if (!t) return 0; t = t.replace(/[€\s]/g,''); if (t.includes(',')) t = t.replace(/\./g,'').replace(',', '.'); return parseFloat(t) || 0; };
const fecha = (t) => { const m = (t||'').match(/(\d{1,2})[\/\-.](\d{1,2})[\/\-.](\d{4})/); return m ? `${m[3]}-${m[2].padStart(2,'0')}-${m[1].padStart(2,'0')}` : ''; };
const salida = [];
for (const item of $input.all()) {
  const texto = item.json.text;
  const lineas = texto.split('\n').map(l => l.trim()).filter(Boolean);
  const buscar = (re) => { for (const l of lineas) { const m = l.match(re); if (m) return m[1]; } return ''; };
  const detalle = [];
  for (const l of lineas) {
    const m = l.match(/^(.+?)\s+(\d+(?:[.,]\d+)?)\s+([\d.,]+)\s*€?\s+(?:(\d+(?:[.,]\d+)?)\s*%\s+)?([\d.,]+)\s*€?$/);
    if (m && !/total|base|iva/i.test(m[1])) detalle.push({ concepto: m[1], cantidad: num(m[2]), precioUnitario: num(m[3]), descuento: num(m[4]), importe: num(m[5]) });
  }
  salida.push({ json: {
    numero: buscar(/n[ºo°]\s*factura\s*[:.]?\s*(\S+)/i),
    proveedor: buscar(/^emisor\s*[:.]\s*(.+)$/i),
    proveedorNif: buscar(/NIF\s*[:.]?\s*(\w+)/i),
    cliente: buscar(/^cliente\s*[:.]\s*(.+)$/i),
    clienteNif: '',
    fechaEmision: fecha(buscar(/emisi[oó]n\s*[:.]?\s*(\S+)/i)),
    fechaVencimiento: fecha(buscar(/vencimiento\s*[:.]?\s*(\S+)/i)),
    baseImponible: num(buscar(/base\s*imponible\s*:?\s*([\d.,]+)/i)),
    impuestos: num(buscar(/IVA\s*\(?[\d.,]*%?\)?\s*:?\s*([\d.,]+)\s*€/i)),
    total: num(buscar(/^total\s*:?\s*([\d.,]+)/i)),
    estado: 'pendiente',
    archivo: $('2. Filtrar solo PDF').item.json.archivo,
    remitente: $('2. Filtrar solo PDF').item.json.remitente,
    fechaRecepcion: new Date().toISOString().slice(0,10),
    lineas: detalle
  }});
}
return salida;
